create table if not exists public.fleet_performance_events (id uuid primary key default gen_random_uuid(),fleet_driver_id uuid references public.fleet_drivers(id) on delete set null,fleet_vehicle_id uuid references public.fleet_vehicles(id) on delete set null,route_id uuid references public.fleet_routes(id) on delete set null,event_type text not null,occurred_at timestamptz not null default now(),latitude double precision,longitude double precision,metrics jsonb not null default '{}'::jsonb,network_event_id uuid references public.notification_events(id) on delete set null); create index if not exists idx_fleet_performance_events_driver_time on public.fleet_performance_events(fleet_driver_id,occurred_at desc); create index if not exists idx_fleet_performance_events_route_time on public.fleet_performance_events(route_id,occurred_at desc); create table if not exists public.enterprise_intelligence_events (id uuid primary key default gen_random_uuid(),network_id uuid not null references public.enterprise_partner_networks(id) on delete cascade,location_id uuid references public.locations(id) on delete set null,event_type text not null,occurred_at timestamptz not null default now(),metrics jsonb not null default '{}'::jsonb,source_event_id uuid references public.notification_events(id) on delete set null); create index if not exists idx_enterprise_intelligence_events_network_time on public.enterprise_intelligence_events(network_id,occurred_at desc); create table if not exists public.qr_intelligence_events (id uuid primary key default gen_random_uuid(),qr_code_id uuid not null references public.qr_codes(id) on delete cascade,location_id uuid references public.locations(id) on delete set null,user_id uuid references auth.users(id) on delete set null,redemption_id uuid references public.qr_redemptions(id) on delete set null,event_type text not null,actor_context text not null default 'consumer',occurred_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb); create index if not exists idx_qr_intelligence_events_qr_time on public.qr_intelligence_events(qr_code_id,occurred_at desc); create index if not exists idx_qr_intelligence_events_location_time on public.qr_intelligence_events(location_id,occurred_at desc); alter table public.fleet_performance_events enable row level security; alter table public.enterprise_intelligence_events enable row level security; alter table public.qr_intelligence_events enable row level security; create policy fleet_performance_events_authenticated_read on public.fleet_performance_events for select to authenticated using(true); create policy enterprise_intelligence_events_authenticated_read on public.enterprise_intelligence_events for select to authenticated using(true); create policy qr_intelligence_events_own_read on public.qr_intelligence_events for select to authenticated using(user_id=auth.uid());
